package com.opensocket.aievent.core.a2a;
import java.time.OffsetDateTime;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Repository;
@Repository @Profile("!prod") @ConditionalOnProperty(prefix="task",name="store",havingValue="MEMORY",matchIfMissing=true)
public class InMemoryA2AReconciliationCaseRepository implements A2AReconciliationCaseRepository {private final Map<String,A2AReconciliationCase> values=new ConcurrentHashMap<>();private String k(String t,String id){return t+"|"+id;}public synchronized A2AReconciliationCase save(A2AReconciliationCase v){values.put(k(v.getTenantId(),v.getCaseId()),v);return v;}public synchronized A2AReconciliationCase saveExpectedVersion(A2AReconciliationCase v,long e){A2AReconciliationCase c=values.get(k(v.getTenantId(),v.getCaseId()));if(c==null||c.getVersion()!=e)throw new IllegalStateException("RESOURCE_VERSION_CONFLICT");values.put(k(v.getTenantId(),v.getCaseId()),v);return v;}public Optional<A2AReconciliationCase> findById(String t,String id){return Optional.ofNullable(values.get(k(t,id)));}public Optional<A2AReconciliationCase> findOpenByCancellation(String t,String id){return values.values().stream().filter(v->t.equals(v.getTenantId())&&id.equals(v.getCancellationId())&&v.active()).findFirst();}public Optional<A2AReconciliationCase> findOpenByRequest(String t,String id){return values.values().stream().filter(v->t.equals(v.getTenantId())&&id.equals(v.getRequestId())&&v.active()).findFirst();}public List<A2AReconciliationCase> findOpen(String t,int l){return values.values().stream().filter(v->t.equals(v.getTenantId())&&v.active()).limit(l).toList();}public synchronized List<A2AReconciliationCase> claimDue(String worker,OffsetDateTime now,OffsetDateTime until,int limit){List<A2AReconciliationCase> out=new ArrayList<>();for(A2AReconciliationCase v:values.values()){if(out.size()>=limit)break;if(!v.active()||v.getStatus()==A2AReconciliationStatus.WAIT_HUMAN||v.getNextAttemptAt()!=null&&v.getNextAttemptAt().isAfter(now)||v.getClaimUntil()!=null&&v.getClaimUntil().isAfter(now))continue;v.setStatus(A2AReconciliationStatus.CLAIMED);v.setClaimedBy(worker);v.setClaimTokenHash(Integer.toHexString(Objects.hash(v.getCaseId(),worker,now)));v.setClaimUntil(until);v.setHeartbeatAt(now);v.setRepairAttemptNo(v.getRepairAttemptNo()+1);v.setVersion(v.getVersion()+1);out.add(v);}return List.copyOf(out);}public synchronized List<A2AReconciliationCase> claimExecutable(String worker,OffsetDateTime now,OffsetDateTime until,int limit){List<A2AReconciliationCase> out=new ArrayList<>();for(A2AReconciliationCase v:values.values()){if(out.size()>=limit)break;if(v.getStatus()!=A2AReconciliationStatus.READY||v.getClaimUntil()!=null&&v.getClaimUntil().isAfter(now))continue;v.setStatus(A2AReconciliationStatus.EXECUTING);v.setClaimedBy(worker);v.setClaimTokenHash(Integer.toHexString(Objects.hash(v.getCaseId(),worker,now)));v.setClaimUntil(until);v.setHeartbeatAt(now);v.setRepairAttemptNo(v.getRepairAttemptNo()+1);v.setVersion(v.getVersion()+1);out.add(v);}return List.copyOf(out);}public synchronized boolean heartbeat(String t,String id,String w,long e,OffsetDateTime h,OffsetDateTime u){A2AReconciliationCase v=values.get(k(t,id));if(v==null||v.getVersion()!=e||!Objects.equals(w,v.getClaimedBy()))return false;v.setHeartbeatAt(h);v.setClaimUntil(u);v.setVersion(e+1);return true;}public List<A2AReconciliationCase> search(A2AReconciliationSearchQuery q){return values.values().stream().filter(v->q.tenantId().equals(v.getTenantId())).filter(v->q.status()==null||q.status().isBlank()||v.getStatus().name().equals(q.status())).filter(v->q.caseType()==null||q.caseType().isBlank()||Objects.equals(v.getCaseType(),q.caseType())).skip(q.normalizedOffset()).limit(q.cappedLimit()).toList();}public long count(A2AReconciliationSearchQuery q){return values.values().stream().filter(v->q.tenantId().equals(v.getTenantId())).count();}public String mode(){return "MEMORY";}}
